 if(section==='ride')dailyPanel=createRideApp({container:body,state,speakText:turns=>placeVoice.sayText(turns),speak:ids=>placeVoice.say(ids),commit:commitDaily,guide:guideDaily,location:()=>view,position:()=>player.position});
 if(section==='jobs'){
 body.innerHTML=`<div class="card"><h3>Neighbourhood courier</h3><p>Collect a parcel at Dispatch. Use the red work bike outside, or walk to Provisions. Stop and dismount before taking the parcel inside.</p><p>${state.delivery?.status==='carrying'?'Carrying parcel #'+state.delivery.id+' · '+naira(state.delivery.pay)+' on handover':state.delivery?.status==='return'?'Paid. Return home to complete your round.':'Pay from ₦1,200 · rider skill '+state.skills.rider}</p><button id="job-rider">${state.delivery?.status==='carrying'?'Guide to delivery':state.delivery?.status==='return'?'Guide home':'Guide to Dispatch'}</button></div><p class="note">Bring the parcel to the provisions counter to get paid. Return the work bike to Dispatch, and go home to finish your round.</p><div class="card"><h3>More local work</h3><p>Trading remains at the provisions counter. Visit local counters for more work.</p><button id="findshop">Find the shop</button></div><div class="card"><h3>Road vehicles</h3><p>Green self-drive hatchback outside Dispatch: one completed parcel round or paid shift, then ₦900 confirmed rental. No ownership included.</p><button id="find-rental">Find Dispatch rental bay</button><button id="recover-vehicle">Recover nearby stuck vehicle · free</button></div>`;
 $('job-rider').onclick=()=>guide(state.delivery?.status==='carrying'?'shop':state.delivery?.status==='return'?'home':'dispatch');$('findshop').onclick=()=>guide('shop');$('find-rental').onclick=()=>guide('dispatch');$('recover-vehicle').onclick=()=>vehicleRecovery();
 }
